const lines = $input.all().map(i => {
  const r = i.json;
  const last = r.last_success ? `last success ${r.days_since} days ago` : 'no success recorded yet';
  return `• ${r.workflow} ${r.label || ''}: expected every ${r.expected}, ${last}.`;
});
return [{ json: {
  text: `⏰ Watchdog: ${lines.length} workflow(s) overdue\n` + lines.join('\n') + `\nCheck: is it published? Did its trigger change? (handover pack, section 4)`,
  workflows: $input.all().map(i => i.json.workflow)
} }];

